#include <windows.h>
#include <stdio.h>

int main() {
    if (!OpenClipboard(nullptr)) {
        return 1;
    }

    HANDLE data = GetClipboardData(CF_UNICODETEXT);
    if (data != nullptr) {
        auto text = static_cast<const wchar_t*>(GlobalLock(data));
        if (text != nullptr) {
            // Report only the length so clipboard contents are not exposed.
            printf("Clipboard text length: %zu characters.\n", wcslen(text));
            GlobalUnlock(data);
        }
    }

    CloseClipboard();
    return 0;
}

