#include <windows.h>
#include <stdio.h>

static bool g_received = false;
static UINT g_size = 0;
static BYTE g_buffer[sizeof(RAWINPUT) + 64] = {};

static LRESULT CALLBACK WndProc(HWND window, UINT message, WPARAM wParam,
    LPARAM lParam) {
    if (message == WM_INPUT) {
        UINT size = sizeof(g_buffer);
        UINT written = GetRawInputData(reinterpret_cast<HRAWINPUT>(lParam),
            RID_INPUT, g_buffer, &size, sizeof(RAWINPUTHEADER));
        if (written != static_cast<UINT>(-1)) {
            g_size = written;
            g_received = true;
        }
        return 0;
    }
    return DefWindowProcW(window, message, wParam, lParam);
}

int main() {
    WNDCLASSW windowClass = {};
    windowClass.lpfnWndProc = WndProc;
    windowClass.hInstance = GetModuleHandleW(nullptr);
    windowClass.lpszClassName = L"NtExplorerRawInputWindow";
    if (!RegisterClassW(&windowClass)) {
        return 1;
    }

    HWND window = CreateWindowExW(0, windowClass.lpszClassName, L"", 0,
        0, 0, 0, 0, HWND_MESSAGE, nullptr, windowClass.hInstance, nullptr);
    if (window == nullptr) {
        return 1;
    }

    RAWINPUTDEVICE device = {};
    device.usUsagePage = 0x01;
    device.usUsage = 0x02; // Mouse.
    device.dwFlags = RIDEV_INPUTSINK;
    device.hwndTarget = window;
    if (!RegisterRawInputDevices(&device, 1, sizeof(device))) {
        printf("RegisterRawInputDevices failed: %lu\n", GetLastError());
        return 1;
    }

    INPUT input = {};
    input.type = INPUT_MOUSE;
    input.mi.dx = 1;
    input.mi.dy = 1;
    input.mi.dwFlags = MOUSEEVENTF_MOVE;
    SendInput(1, &input, sizeof(input));

    DWORD deadline = GetTickCount() + 2000;
    MSG message = {};
    while (!g_received && GetTickCount() < deadline) {
        while (PeekMessageW(&message, window, 0, 0, PM_REMOVE)) {
            TranslateMessage(&message);
            DispatchMessageW(&message);
        }
        Sleep(10);
    }

    if (g_received) {
        printf("GetRawInputData returned %u bytes.\n", g_size);
    } else {
        printf("No WM_INPUT message arrived within the timeout.\n");
    }

    device.dwFlags = RIDEV_REMOVE;
    device.hwndTarget = nullptr;
    RegisterRawInputDevices(&device, 1, sizeof(device));
    DestroyWindow(window);
    UnregisterClassW(windowClass.lpszClassName, windowClass.hInstance);
    return 0;
}

