#include <windows.h>
#include <stdio.h>

int main() {
    WNDCLASSW windowClass = {};
    windowClass.lpfnWndProc = DefWindowProcW;
    windowClass.hInstance = GetModuleHandleW(nullptr);
    windowClass.lpszClassName = L"NtExplorerRawInputWindow";
    if (!RegisterClassW(&windowClass)) {
        return 1;
    }

    HWND window = CreateWindowExW(0, windowClass.lpszClassName, L"", 0,
        0, 0, 0, 0, HWND_MESSAGE, nullptr, windowClass.hInstance, nullptr);
    if (window == nullptr) {
        return 1;
    }

    RAWINPUTDEVICE devices[2] = {};
    devices[0].usUsagePage = 0x01;
    devices[0].usUsage = 0x06; // Keyboard.
    devices[0].dwFlags = RIDEV_INPUTSINK;
    devices[0].hwndTarget = window;
    devices[1].usUsagePage = 0x01;
    devices[1].usUsage = 0x02; // Mouse.
    devices[1].dwFlags = RIDEV_INPUTSINK;
    devices[1].hwndTarget = window;

    BOOL registered = RegisterRawInputDevices(devices, 2,
        sizeof(RAWINPUTDEVICE));
    printf("RegisterRawInputDevices: %s\n",
        registered ? "registered" : "failed");

    if (registered) {
        devices[0].dwFlags = RIDEV_REMOVE;
        devices[0].hwndTarget = nullptr;
        devices[1].dwFlags = RIDEV_REMOVE;
        devices[1].hwndTarget = nullptr;
        RegisterRawInputDevices(devices, 2, sizeof(RAWINPUTDEVICE));
    }

    DestroyWindow(window);
    UnregisterClassW(windowClass.lpszClassName, windowClass.hInstance);
    return 0;
}

#include <windows.h>
#include <stdio.h>

int main() {
    if (!OpenClipboard(nullptr)) {
        return 1;
    }

    // Save the existing text so the example can restore it.
    HANDLE previous = GetClipboardData(CF_UNICODETEXT);
    HGLOBAL saved = nullptr;
    if (previous != nullptr) {
        auto text = static_cast<const wchar_t*>(GlobalLock(previous));
        if (text != nullptr) {
            SIZE_T bytes = (wcslen(text) + 1) * sizeof(wchar_t);
            saved = GlobalAlloc(GMEM_MOVEABLE, bytes);
            if (saved != nullptr) {
                memcpy(GlobalLock(saved), text, bytes);
                GlobalUnlock(saved);
            }
            GlobalUnlock(previous);
        }
    }

    const wchar_t example[] = L"NtExplorer example";
    HGLOBAL data = GlobalAlloc(GMEM_MOVEABLE, sizeof(example));
    if (data != nullptr) {
        memcpy(GlobalLock(data), example, sizeof(example));
        GlobalUnlock(data);
        SetClipboardData(CF_UNICODETEXT, data);
    }

    if (saved != nullptr) {
        // Restoring after SetClipboardData keeps the user's text intact.
        EmptyClipboard();
        SetClipboardData(CF_UNICODETEXT, saved);
    }

    CloseClipboard();
    return 0;
}
